/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type ReorderContext, type ReorderInput, advance, aim, drawn, elsewhere, elsewhereStill, follow, fresh, grab, land, lift, lifts, movable, nudge, nudges, nudging, own, ownStill, passes, propose, proposeAt, renew, same, sameGlides, sameStill, sameStillGlides, stepping, steps, take, tick } from './machine.js'

export type { ReorderContext, ReorderInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'reorder'

/** The state `held`. */
export const STATE_HELD = 0
/** The state `idle`. */
export const STATE_IDLE = 1
/** The state `landing`. */
export const STATE_LANDING = 2
/** The state `dragging`. */
export const STATE_DRAGGING = 3
/** The state `pressed`. */
export const STATE_PRESSED = 4
/** The state `returning`. */
export const STATE_RETURNING = 5
/** Each state's name, by its number. */
export const STATES = ['held', 'idle', 'landing', 'dragging', 'pressed', 'returning'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['held', 'idle', 'landing', 'pointing', 'dragging', 'pressed', 'returning'] as const

/** The event `PICK`. */
export const EVENT_PICK = 0
/** The event `STEP`. */
export const EVENT_STEP = 1
/** The event `TARGET`. */
export const EVENT_TARGET = 2
/** The event `DROP`. */
export const EVENT_DROP = 3
/** The event `CANCEL`. */
export const EVENT_CANCEL = 4
/** The event `NUDGE`. */
export const EVENT_NUDGE = 5
/** The event `PRESS`. */
export const EVENT_PRESS = 6
/** The event `DRAG`. */
export const EVENT_DRAG = 7
/** The event `RELEASE`. */
export const EVENT_RELEASE = 8
/** The event `TICK`. */
export const EVENT_TICK = 9
/** The event `LANDED`. */
export const EVENT_LANDED = 10
/** The event `GLIDED`. */
export const EVENT_GLIDED = 11
/** Each event's name, by its number. */
export const EVENTS = ['PICK', 'STEP', 'TARGET', 'DROP', 'CANCEL', 'NUDGE', 'PRESS', 'DRAG', 'RELEASE', 'TICK', 'LANDED', 'GLIDED'] as const

/** The effect `lift`. */
export const EFFECT_LIFT = 0
/** The effect `frame`. */
export const EFFECT_FRAME = 1
/** The effect `pass`. */
export const EFFECT_PASS = 2
/** The effect `scroll`. */
export const EFFECT_SCROLL = 3
/** The effect `listen`. */
export const EFFECT_LISTEN = 4
/** The effect `unlisten`. */
export const EFFECT_UNLISTEN = 5
/** The effect `untrack`. */
export const EFFECT_UNTRACK = 6
/** The effect `picked-up`. */
export const EFFECT_PICKED_UP = 7
/** The effect `moved`. */
export const EFFECT_MOVED = 8
/** The effect `dropped`. */
export const EFFECT_DROPPED = 9
/** The effect `canceled`. */
export const EFFECT_CANCELED = 10
/** The effect `refocus`. */
export const EFFECT_REFOCUS = 11
/** The effect `land`. */
export const EFFECT_LAND = 12
/** The effect `back`. */
export const EFFECT_BACK = 13
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 14
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 15
/** Each effect's name, by its number. */
export const EFFECTS = ['lift', 'frame', 'pass', 'scroll', 'listen', 'unlisten', 'untrack', 'picked-up', 'moved', 'dropped', 'canceled', 'refocus', 'land', 'back', 'deadline', 'deadline-end'] as const

/** The request event `before-reorder`. */
export const ASK_BEFORE_REORDER = 0
/** The request event `reorder`. */
export const ASK_REORDER = 1
/** Each request event's name, by its number. */
export const ASKS = ['before-reorder', 'reorder'] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: ReorderContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (_context: ReorderContext): number =>
  STATE_IDLE

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_LANDING:
      return [[EFFECT_LAND], [EFFECT_DEADLINE, { ms: 1000, owner: 2 }]]
    case STATE_DRAGGING:
      return [[EFFECT_LIFT], [EFFECT_FRAME], [EFFECT_LISTEN]]
    case STATE_RETURNING:
      return [[EFFECT_BACK]]
  }
  return []
}

/** What `held` does with each event. */
const inHeld = (context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PICK:
      return ownStill(context, input) ? { context: context, effects: [[EFFECT_DROPPED]], state: STATE_IDLE } : own(context, input) ? { accept: { context: propose(context, input), effects: [[EFFECT_DROPPED], [EFFECT_REFOCUS]], state: STATE_IDLE }, ask: [ASK_BEFORE_REORDER, ASK_REORDER], refuse: { context: context, effects: [[EFFECT_CANCELED]], state: STATE_IDLE } } : undefined
    case EVENT_STEP:
      return steps(context, input) ? { context: advance(context, input), effects: [[EFFECT_MOVED]], state: STATE_HELD } : stepping(context, input) ? { context: context, effects: [], state: STATE_HELD } : undefined
    case EVENT_TARGET:
      return elsewhereStill(context, input) ? { context: aim(context, input), effects: [[EFFECT_DROPPED]], state: STATE_IDLE } : elsewhere(context, input) ? { accept: { context: proposeAt(context, input), effects: [[EFFECT_DROPPED], [EFFECT_REFOCUS]], state: STATE_IDLE }, ask: [ASK_BEFORE_REORDER, ASK_REORDER], refuse: { context: context, effects: [[EFFECT_CANCELED]], state: STATE_IDLE } } : undefined
    case EVENT_DROP:
      return sameStill(context, input) ? { context: context, effects: [[EFFECT_DROPPED]], state: STATE_IDLE } : same(context, input) ? { accept: { context: propose(context, input), effects: [[EFFECT_DROPPED], [EFFECT_REFOCUS]], state: STATE_IDLE }, ask: [ASK_BEFORE_REORDER, ASK_REORDER], refuse: { context: context, effects: [[EFFECT_CANCELED]], state: STATE_IDLE } } : undefined
    case EVENT_CANCEL:
      return same(context, input) ? { context: context, effects: [[EFFECT_CANCELED]], state: STATE_IDLE } : undefined
  }
  return undefined
}

/** What `idle` does with each event. */
const inIdle = (context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PICK:
      return movable(context, input) ? { context: take(context, input), effects: [[EFFECT_PICKED_UP]], state: STATE_HELD } : undefined
    case EVENT_NUDGE:
      return nudges(context, input) ? { accept: { context: nudge(context, input), effects: [[EFFECT_MOVED], [EFFECT_REFOCUS]], state: STATE_IDLE }, ask: [ASK_BEFORE_REORDER, ASK_REORDER], refuse: { context: nudge(context, input), effects: [[EFFECT_CANCELED]], state: STATE_IDLE } } : nudging(context, input) ? { context: context, effects: [], state: STATE_IDLE } : undefined
    case EVENT_PRESS:
      return movable(context, input) ? { context: grab(context, input), effects: [], state: STATE_PRESSED } : undefined
  }
  return undefined
}

/** What `landing` does with each event. */
const inLanding = (context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_LANDED:
      return drawn(context, input) ? { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 2 }]], state: STATE_IDLE } : undefined
  }
  return undefined
}

/** What `dragging` does with each event. */
const inDragging = (context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CANCEL:
      return sameGlides(context, input) ? { context: renew(context), effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_CANCELED], [EFFECT_BACK]], state: STATE_RETURNING } : same(context, input) ? { context: context, effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_CANCELED]], state: STATE_IDLE } : undefined
    case EVENT_DRAG:
      return passes(context, input) ? { context: follow(context, input), effects: [[EFFECT_PASS]], state: STATE_DRAGGING } : undefined
    case EVENT_RELEASE:
      return sameStillGlides(context, input) ? { context: renew(context), effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_DROPPED], [EFFECT_BACK]], state: STATE_RETURNING } : sameStill(context, input) ? { context: context, effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_DROPPED]], state: STATE_IDLE } : sameGlides(context, input) ? { accept: { context: land(context, input), effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_DROPPED], [EFFECT_LAND], [EFFECT_DEADLINE, { ms: 1000, owner: 2 }]], state: STATE_LANDING }, ask: [ASK_BEFORE_REORDER, ASK_REORDER], refuse: { context: renew(context), effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_CANCELED], [EFFECT_BACK]], state: STATE_RETURNING } } : same(context, input) ? { accept: { context: propose(context, input), effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_DROPPED]], state: STATE_IDLE }, ask: [ASK_BEFORE_REORDER, ASK_REORDER], refuse: { context: context, effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK], [EFFECT_CANCELED]], state: STATE_IDLE } } : undefined
    case EVENT_TICK:
      return fresh(context, input) ? { context: tick(context, input), effects: [[EFFECT_SCROLL], [EFFECT_FRAME]], state: STATE_DRAGGING } : undefined
  }
  return undefined
}

/** What `pressed` does with each event. */
const inPressed = (context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CANCEL:
      return same(context, input) ? { context: context, effects: [[EFFECT_UNTRACK]], state: STATE_IDLE } : undefined
    case EVENT_DRAG:
      return lifts(context, input) ? { context: lift(context, input), effects: [[EFFECT_LIFT], [EFFECT_FRAME], [EFFECT_LISTEN]], state: STATE_DRAGGING } : undefined
    case EVENT_RELEASE:
      return same(context, input) ? { context: context, effects: [[EFFECT_UNTRACK]], state: STATE_IDLE } : undefined
  }
  return undefined
}

/** What `returning` does with each event. */
const inReturning = (context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_GLIDED:
      return fresh(context, input) ? { context: context, effects: [], state: STATE_IDLE } : undefined
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: ReorderContext, event: number, input: ReorderInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_HELD:
      return inHeld(context, event, input)
    case STATE_IDLE:
      return inIdle(context, event, input)
    case STATE_LANDING:
      return inLanding(context, event, input)
    case STATE_DRAGGING:
      return inDragging(context, event, input)
    case STATE_PRESSED:
      return inPressed(context, event, input)
    case STATE_RETURNING:
      return inReturning(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: ReorderContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_LANDING:
      return owner === 2 ? { context: renew(context), effects: [[EFFECT_DEADLINE_END, { owner: 2 }], [EFFECT_BACK]], state: STATE_RETURNING } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (state: number, context: ReorderContext): Move | undefined => {
  switch (state) {
    case STATE_HELD:
      return { context: context, effects: [], state: STATE_IDLE }
    case STATE_IDLE:
      return { context: context, effects: [], state: STATE_IDLE }
    case STATE_LANDING:
      return { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 2 }]], state: STATE_IDLE }
    case STATE_DRAGGING:
      return { context: context, effects: [[EFFECT_UNLISTEN], [EFFECT_UNTRACK]], state: STATE_IDLE }
    case STATE_PRESSED:
      return { context: context, effects: [[EFFECT_UNTRACK]], state: STATE_IDLE }
    case STATE_RETURNING:
      return { context: context, effects: [], state: STATE_IDLE }
  }
  return undefined
}

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
